content:
Here are the domain objects:
```json
{
  "domain objects": [
    {
      "name": "Seller",
      "description": "User who lists and sells second-hand items."
    },
    {
      "name": "Item Listing",
      "description": "Entry in the marketplace showing an item’s details and price.",
      "attributes": [
        "Item",
        "Price"
      ]
    },
    {
      "name": "Item",
      "description": "The physical or digital good being sold."
    },
    {
      "name": "Price",
      "description": "The monetary value set for the listed item."
    },
    {
      "name": "Buyer",
      "description": "User who browses listings and purchases items."
    },
    {
      "name": "Order",
      "description": "Purchase request created by a buyer for a specific listing."
    },
    {
      "name": "Package",
      "description": "Container prepared by the seller to ship the sold item.",
      "attributes": [
        "Item"
      ]
    },
    {
      "name": "Shipping Carrier",
      "description": "Company responsible for delivering packages from sellers to buyers."
    },
    {
      "name": "Marketplace Catalogue",
      "description": "Collection of all item listings available in the marketplace.",
      "attributes": [
        "Item Listing"
      ]
    },
    {
      "name": "Shipment",
      "description": "Delivery process that tracks the package’s status.",
      "attributes": [
        "Status"
      ]
    },
    {
      "name": "Status",
      "description": "Current state of the shipment (e.g., pending, in transit, delivered)."
    },
    {
      "name": "Message",
      "description": "Communication sent between buyer and seller."
    },
    {
      "name": "Dispatch Confirmation",
      "description": "Notification confirming the item has been shipped."
    },
    {
      "name": "Feedback",
      "description": "Review left by a buyer about the seller or item."
    },
    {
      "name": "Marketplace Administrator",
      "description": "Person who oversees listings and manages marketplace operations."
    },
    {
      "name": "Refund Request",
      "description": "Request submitted by a buyer for reimbursement after an issue."
    }
  ]
}
```
